pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a minimal ERC20-like token that reverts on transferFrom
        Token token = new Token();
        address from = address(0x1234);
        address[] memory tos = new address[](1);
        tos[0] = address(0x5678);
        uint v = 100;

        // The transfer call will succeed but the token's transferFrom reverts
        // Since require(_s) will fail, we wrap in try/catch
        bool ok;
        try c.transfer(from, address(token), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        // REFERENCE returns true (the call reverts but reference returns true due to bug? Actually reference requires(_s) so it reverts... Wait both revert? No, reference has return true, but if require(_s) fails it reverts. So both will revert for a reverting token. Need a token that succeeds but different behavior.
        // Actually the only difference is return true vs return false. Both call require(_s) which fails if token reverts. So both revert. Need token that succeeds.
        // Let's use a token that always succeeds (returns true).
        TokenOk tokenOk = new TokenOk();
        try c.transfer(from, address(tokenOk), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok); // Reference returns true, modified returns false but does not revert
    }
}

contract Token {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert("fail");
    }
}

contract TokenOk {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Concrete scenario: call transfer with a non-existent contract address
        // so that the internal call should revert. The reference version's require(_s)
        // will cause the outer call to revert; the buggy version skips require and returns true.
        address from = address(0x1234);
        address nonExistent = address(0xDEAD); // no code at this address
        address[] memory tos = new address[](1);
        tos[0] = address(0x5678);
        uint v = 100;
        bool ok;
        try c.transfer(from, nonExistent, tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference reverts => ok false; buggy returns true => ok true.
        // Assert that ok is true: this fails on the buggy version (actually reference also fails if we assertTrue(ok)).
        // Wait — we want reference PASSES, buggy FAILS.
        // Reference: reverts => ok = false => assertTrue(false) would FAIL — that's wrong.
        // We need assertion that reference holds and buggy breaks.
        // Reference reverts => ok false; buggy returns true => ok true.
        // So if we assertTrue(!ok), reference has !ok = true (passes), buggy has !ok = false (fails).
        // But the instruction says: "End with exactly one assertion the reference satisfies AND the second version breaks FOR THIS CONCRETE SCENARIO".
        // For reference: !ok is true; for buggy: !ok is false. So assertTrue(!ok) will pass reference, fail buggy.
        assertTrue(!ok);
    }
}
